import{_ as s,c as t,o as e,a2 as i}from"./chunks/framework.CIiVzG-O.js";const g=JSON.parse('{"title":"macOS の権限","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/permissions.md","filePath":"ja/guide/permissions.md","lastUpdated":1793163976000}'),r={name:"ja/guide/permissions.md"};function n(o,a,p,l,h,d){return e(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="macos-の権限" tabindex="-1">macOS の権限 <a class="header-anchor" href="#macos-の権限" aria-label="Permalink to &quot;macOS の権限&quot;">​</a></h1><p>NueZip は、最良の体験を提供するためにいくつかの macOS 権限を要求する場合があります。このページでは、各権限の目的と管理方法について説明します。</p><h2 id="ファイルとフォルダ" tabindex="-1">ファイルとフォルダ <a class="header-anchor" href="#ファイルとフォルダ" aria-label="Permalink to &quot;ファイルとフォルダ&quot;">​</a></h2><p>システム上のあらゆる場所にあるアーカイブにアクセスするために、NueZip はファイルアクセス権限を必要とします。</p><p><strong>用途</strong>: アーカイブファイルの読み取り、内容の展開、新しいアーカイブの作成。</p><p><strong>管理</strong>: システム設定 → <strong>プライバシーとセキュリティ</strong> → <strong>ファイルとフォルダ</strong></p><p>初回起動時にプロンプトが表示されたらアクセスを許可してください。アクセスはいつでも管理または取り消しができます。</p><h2 id="finder-機能拡張" tabindex="-1">Finder 機能拡張 <a class="header-anchor" href="#finder-機能拡張" aria-label="Permalink to &quot;Finder 機能拡張&quot;">​</a></h2><p>NueZip には、右クリックのコンテキストメニューオプションを追加する Finder 機能拡張が含まれています。</p><p><strong>用途</strong>: Finder から直接、アーカイブファイルを右クリックして NueZip で展開、圧縮、または開く。</p><p><strong>有効化</strong>: システム設定 → <strong>プライバシーとセキュリティ</strong> → <strong>機能拡張</strong> → <strong>Finder 機能拡張</strong> → <strong>NueZip</strong> を有効にする</p><h2 id="通知" tabindex="-1">通知 <a class="header-anchor" href="#通知" aria-label="Permalink to &quot;通知&quot;">​</a></h2><p>NueZip は、長時間実行される操作（バッチ展開、大容量アーカイブの圧縮）に対して通知を表示する場合があります。</p><p><strong>用途</strong>: バックグラウンド操作の完了をお知らせすること。</p><p><strong>管理</strong>: システム設定 → <strong>通知</strong> → <strong>NueZip</strong></p><h2 id="全ディスクアクセス-オプション" tabindex="-1">全ディスクアクセス（オプション） <a class="header-anchor" href="#全ディスクアクセス-オプション" aria-label="Permalink to &quot;全ディスクアクセス（オプション）&quot;">​</a></h2><p>システムで保護された場所にアーカイブを展開するために、NueZip は全ディスクアクセスを要求する場合があります。</p><p><strong>用途</strong>: ユーザーフォルダ外の場所へ展開されたファイルを書き込むこと。</p><p><strong>管理</strong>: システム設定 → <strong>プライバシーとセキュリティ</strong> → <strong>全ディスクアクセス</strong></p><p>この権限はオプションであり、システム全体の場所を扱う場合にのみ必要です。</p><h2 id="ターミナルで権限をリセットする" tabindex="-1">ターミナルで権限をリセットする <a class="header-anchor" href="#ターミナルで権限をリセットする" aria-label="Permalink to &quot;ターミナルで権限をリセットする&quot;">​</a></h2><p>権限ダイアログが閉じられたり、状態が不整合になったりした場合は、<code>tccutil</code> を使用して macOS の権限プロンプトをリセットできます：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># NueZip の権限をリセットする</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tccutil</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> All</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.w3cub.nuezip</span></span></code></pre></div><p><code>tccutil</code> の実行後、アプリを再起動し、再度その機能を呼び出すとプロンプトが再表示されます。</p><h2 id="トラブルシューティング" tabindex="-1">トラブルシューティング <a class="header-anchor" href="#トラブルシューティング" aria-label="Permalink to &quot;トラブルシューティング&quot;">​</a></h2><ul><li>通知が表示されない場合は、<strong>通知</strong> 権限が許可されているか確認してください。</li><li>権限を変更した後は、変更を反映させるために必ず NueZip を終了して再起動してください。</li></ul><p>詳しくは <a href="./troubleshooting.html">トラブルシューティングガイド</a> を参照してください。</p>`,27)])])}const u=s(r,[["render",n]]);export{g as __pageData,u as default};
